def tenumerate(iterable, start=0, total=None, tqdm_class=tqdm_auto, **tqdm_kwargs):
    """
    Equivalent of `numpy.ndenumerate` or builtin `enumerate`.

    Parameters
    ----------
    tqdm_class  : [default: tqdm.auto.tqdm].
    """
    try:
        import numpy as np
    except ImportError:
        np = None  # Set to None to avoid future import issues.

    if np is not None and isinstance(iterable, np.ndarray):
        total = total if total is not None else np.prod(iterable.shape)
        return tqdm_class(np.ndenumerate(iterable), total=total, **tqdm_kwargs)

    # For non-ndarray iterables, calculate total if not provided.
    total = total if total is not None else len(iterable)

    return enumerate(tqdm_class(iterable, start=start, total=total, **tqdm_kwargs))
